export const QUESTIONS=banks.flatMap((bank,course)=>bank.map(([question,a,b,c,explanation,source],i)=>({id:`r3-${course}-${i}`,course,expert:i>=12,...(i>=12?{mascot:i%2?'riks':'arkiv'}:{}),category:THEMES[course].theme,question,options:[a,b,c],correct:0,explanation,source})));
const lastSeen=new Map();
export function shuffled(items,random=Math.random){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;}
export function createQuestionDeck(course,random=Math.random){const seen=lastSeen.get(course)||new Set();const ordered=expert=>{const all=QUESTIONS.filter(q=>q.course===course&&q.expert===expert);return [...shuffled(all.filter(q=>!seen.has(q.id)),random),...shuffled(all.filter(q=>seen.has(q.id)),random)];};return {course,standard:ordered(false),expert:ordered(true),seen:new Set(),random};}
export function nextQuestion(deck,expert=false){const pool=expert?deck.expert:deck.standard;if(!pool.length)return null;const original=pool.shift();deck.seen.add(original.id);lastSeen.set(deck.course,deck.seen);const indices=shuffled([0,1,2],deck.random);return {...original,options:indices.map(i=>original.options[i]),correct:indices.indexOf(original.correct)};}
